/* =============================================================================
 * BUILD PROMPT - POVO AI Guidance, Call Prep v1
 *
 * Contract (docs/ARCHITECTURE.md section 6):
 *   request  {request_id, category, participant:{...}, interactions:[{date,
 *             type_label, summary}], candidates:[{point_id, pillar, text,
 *             detail}], max_points: 3}
 *   response {ok:true, ordered_point_ids, insights} | {ok:false, reason}
 *
 * This node never throws. A request that breaks the contract becomes
 * {valid:false, reason}; "Request Valid?" sends it to "Reject Request", which
 * answers {ok:false, reason} and the backend falls back to the POC rules.
 *
 * The model only CHOOSES and ORDERS point_ids. The approved (MLR) text of a
 * point is never sent back, so it cannot be altered on the way through.
 * ========================================================================== */
const body = ($input.first().json || {}).body || {};
const reject = (reason) => [{ json: { valid: false, reason: String(reason).slice(0, 200) } }];

const CATEGORY_LABEL = {
  messaging: 'Suggested Messaging',
  objection: 'Potential Objections',
  closing: 'Suggested Closing Statements',
};
const str = (v) => (v === null || v === undefined ? '' : String(v)).replace(/\s+/g, ' ').trim();

const requestId = str(body.request_id);
if (!requestId) return reject('missing request_id');

// Accept "objections" as well as "objection"; the stored value is singular.
const category = str(body.category).toLowerCase().replace(/s$/, '');
if (!CATEGORY_LABEL[category]) return reject('unknown category: ' + str(body.category));

const participant = body.participant && typeof body.participant === 'object' ? body.participant : null;
if (!participant) return reject('missing participant');

const rawCandidates = Array.isArray(body.candidates) ? body.candidates : [];
const candidates = rawCandidates
  .filter((c) => c && str(c.point_id) && str(c.text))
  .map((c) => ({ point_id: str(c.point_id), pillar: str(c.pillar), text: str(c.text), detail: str(c.detail) }));
if (!candidates.length) return reject('no candidates');
const ids = candidates.map((c) => c.point_id);
if (new Set(ids).size !== ids.length) return reject('duplicate candidate point_id');

// Contract: max_points is 3. Never more than 3, never more than we have.
const requested = parseInt(body.max_points, 10);
const maxPoints = Math.max(1, Math.min(3, Number.isFinite(requested) ? requested : 3, candidates.length));

const interactions = (Array.isArray(body.interactions) ? body.interactions : [])
  .filter((i) => i && (str(i.date) || str(i.summary)))
  .slice(0, 12);

const name = str(participant.display_name) || 'the participant';
const role = str(participant.role_type) || 'HCP';
const withInsights = category === 'messaging';

/* ---------------------------------------------------------------- prompt -- *
 * Kept free of curly braces on purpose: the LLM chain treats the system
 * message as a template, and a stray brace would break it.                  */
const SYSTEM_PROMPT = [
  'You are the call-preparation assistant inside POVO AI Guidance, the field-sales guidance tool for POVO,',
  "Incyte's oral selective JAK1 inhibitor for moderate-to-severe hidradenitis suppurativa (HS).",
  'The reader is a POVO Sales Representative preparing for a call with ' + name + ' (' + role + ').',
  '',
  'YOUR TASK (category: ' + CATEGORY_LABEL[category] + ')',
  '1. Choose up to ' + maxPoints + ' talking points from CANDIDATES that matter most for this participant, most important first.',
  withInsights
    ? '2. For each chosen point write one insight of at most 220 characters that tells the rep why this point fits this participant, grounded in the PARTICIPANT profile and INTERACTIONS.'
    : '2. Do not write insights for this category. Return an empty insights array.',
  '',
  'HOW TO CHOOSE',
  '- Use only the PARTICIPANT profile, the INTERACTIONS and the CANDIDATES below. Do not assume anything else about the participant.',
  '- Messaging: lead with what this participant most needs to hear given decile, segment, competitive focus, HS and POVO patients, and what earlier interactions already covered.',
  '- Objections: pick the objections this participant is most likely to raise given competitive focus, POVO use and recent interactions.',
  '- Closings: pick the closes that match where this participant is now, for example no POVO patients yet versus already prescribing.',
  '',
  'HARD RULES',
  '- The approved text of every candidate is MLR-approved and must never be altered, paraphrased, merged, shortened or re-worded. You return point_ids only, never point text.',
  '- Never invent clinical claims. No efficacy or safety figures, percentages, doses, trial names or results, and no comparisons with other treatments unless they appear word for word in that candidate text.',
  '- Never suggest or imply off-label use. Never give medical advice.',
  '- Every number in an insight must appear in the input (the candidate text, the participant profile or the interactions).',
  '- Use only point_ids listed in CANDIDATES, each at most once, and at most ' + maxPoints + ' of them.',
  '- Tone: plain, professional US English that a rep can read in a few seconds before walking in. Name the participant. No hype, no exclamation marks, no emojis, no markdown.',
  '',
  'OUTPUT',
  'Return JSON only, with no prose and no code fences. Fields:',
  '- ordered_point_ids: array of point_id strings, most important first.',
  '- insights: array of objects with the fields point_id and insight, one per chosen point' + (withInsights ? '.' : '; empty for this category.'),
].join('\n');

const line = (label, value) => (str(value) ? '- ' + label + ': ' + str(value) : null);
const participantBlock = [
  line('Name', participant.display_name),
  line('Role', participant.role_type),
  line('Decile', participant.decile),
  line('Tier', participant.tier_name),
  line('Segment', participant.segment_short_name),
  line('Competitive focus', participant.competitive_focus_label),
  line('HS patients, last 12 months', participant.hs_patients),
  line('POVO patients', participant.povo_patients),
  line('JAK patients', participant.jak_patients),
  line('POVO discussions', participant.povo_discussions),
  line('Last call', participant.last_call_date || 'not called yet'),
].filter(Boolean).join('\n');

const interactionBlock = interactions.length
  ? interactions.map((i) => '- ' + [str(i.date), str(i.type_label), str(i.summary)].filter(Boolean).join(' | ')).join('\n')
  : '- none on record';

const candidateBlock = candidates
  .map((c) => '- point_id: ' + c.point_id + (c.pillar ? '\n  pillar: ' + c.pillar : '') + '\n  approved text: ' + c.text + (c.detail ? '\n  approved detail: ' + c.detail : ''))
  .join('\n');

const USER_PROMPT = [
  'CATEGORY: ' + CATEGORY_LABEL[category],
  'MAX POINTS: ' + maxPoints,
  '',
  'PARTICIPANT',
  participantBlock,
  '',
  'INTERACTIONS (most recent first)',
  interactionBlock,
  '',
  'CANDIDATES',
  candidateBlock,
  '',
  'Return the JSON now.',
].join('\n');

// Numbers the Guard will accept in an insight that is not claim-like.
const factNumbers = [
  participant.decile, participant.hs_patients, participant.povo_patients, participant.jak_patients,
  participant.povo_discussions, participant.last_call_date, participant.tier_name, participant.segment_short_name,
].concat(interactions.map((i) => str(i.date) + ' ' + str(i.summary))).map(str).join(' ');

return [{
  json: {
    valid: true,
    request_id: requestId,
    category,
    max_points: maxPoints,
    with_insights: withInsights,
    candidates,
    fact_text: factNumbers,
    system_prompt: SYSTEM_PROMPT.replace(/[{}]/g, ''),
    user_prompt: USER_PROMPT,
  },
}];

