/* =============================================================================
 * GUARD - POVO AI Guidance, Call Prep v1
 *
 * The model's choice is checked against the candidates it was given. The
 * response is exactly one of:
 *   {ok:true,  ordered_point_ids:[...], insights:{point_id: string}}
 *   {ok:false, reason}
 *
 * Hard failures (ok:false, the backend falls back to the POC rules):
 *   - the output cannot be read as JSON
 *   - ordered_point_ids is not a non-empty array of unique candidate ids,
 *     or has more than max_points entries
 * Soft clean-ups (the answer still ships):
 *   - insights for ids that were not returned are dropped
 *   - insights are only kept for the messaging category (contract)
 *   - a sentence carrying a claim-like number (%, mg, weeks, p-value, fold)
 *     that is not in that point's approved text is stripped; any other number
 *     must be in the approved text or the participant facts
 *   - an insight still over 220 characters after that is dropped, never cut
 * ========================================================================== */
const ctx = $('Build Prompt').first().json;
const raw = $input.first().json || {};
const fail = (reason) => [{ json: { ok: false, reason: String(reason).slice(0, 200) } }];
const MAX_INSIGHT = 220;

function unwrap(value) {
  let v = value;
  for (let i = 0; i < 4; i += 1) {
    if (typeof v === 'string') {
      const s = v.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
      try { v = JSON.parse(s); } catch (e) { return null; }
      continue;
    }
    if (v && typeof v === 'object' && !Array.isArray(v) && v.output !== undefined && Object.keys(v).length <= 2) { v = v.output; continue; }
    if (v && typeof v === 'object' && !Array.isArray(v) && v.text !== undefined && Object.keys(v).length === 1) { v = v.text; continue; }
    break;
  }
  return v && typeof v === 'object' && !Array.isArray(v) ? v : null;
}

try {
  if (raw.error) return fail('model_error: ' + (raw.error.message || raw.error));
  const out = unwrap(raw);
  if (!out) return fail('model output is not a JSON object');

  const byId = new Map(ctx.candidates.map((c) => [c.point_id, c]));
  const ids = Array.isArray(out.ordered_point_ids) ? out.ordered_point_ids.map((x) => String(x).trim()) : null;
  if (!ids || !ids.length) return fail('ordered_point_ids missing or empty');
  if (ids.length > ctx.max_points) return fail('ordered_point_ids has ' + ids.length + ' entries; max_points is ' + ctx.max_points);
  if (new Set(ids).size !== ids.length) return fail('ordered_point_ids contains duplicates');
  const unknown = ids.filter((id) => !byId.has(id));
  if (unknown.length) return fail('ordered_point_ids not in candidates: ' + unknown.join(', '));

  /* --------------------------------------------------------- numbers -- */
  const numbersIn = (text) => new Set((String(text || '').match(/\d[\d,]*(?:\.\d+)?/g) || [])
    .map((t) => t.replace(/,/g, '')).flatMap((t) => [t, String(parseFloat(t))]));
  const factNums = numbersIn(ctx.fact_text);
  const CLAIM_AFTER = /^\s*(%|percent|mg|milligram|weeks?|wks?|-?fold|x\b|times\b)/i;
  const CLAIM_BEFORE = /(HiSCR\s*|p\s*[<=>]\s*|n\s*=\s*)$/i;

  function cleanInsight(text, candidate) {
    const approved = numbersIn(candidate.text + ' ' + candidate.detail);
    const sentences = String(text).replace(/\s+/g, ' ').trim().split(/(?<=[.;!?])\s+/);
    const kept = sentences.filter((s) => {
      const re = /\d[\d,]*(?:\.\d+)?/g;
      let m;
      while ((m = re.exec(s)) !== null) {
        const tok = m[0].replace(/,/g, '');
        const inApproved = approved.has(tok) || approved.has(String(parseFloat(tok)));
        const claimLike = CLAIM_AFTER.test(s.slice(m.index + m[0].length)) || CLAIM_BEFORE.test(s.slice(0, m.index));
        if (claimLike && !inApproved) return false;
        if (!claimLike && !inApproved && !factNums.has(tok) && !factNums.has(String(parseFloat(tok)))) return false;
      }
      return true;
    });
    return kept.join(' ').trim();
  }

  const insights = {};
  if (ctx.with_insights) {
    const list = Array.isArray(out.insights)
      ? out.insights
      : (out.insights && typeof out.insights === 'object'
        ? Object.keys(out.insights).map((k) => ({ point_id: k, insight: out.insights[k] }))
        : []);
    list.forEach((item) => {
      if (!item) return;
      const id = String(item.point_id || '').trim();
      if (!ids.includes(id) || insights[id]) return;
      const text = cleanInsight(item.insight, byId.get(id));
      if (text && text.length <= MAX_INSIGHT) insights[id] = text;
    });
  }

  return [{ json: { ok: true, ordered_point_ids: ids, insights } }];
} catch (e) {
  return fail('guard_error: ' + (e && e.message ? e.message : e));
}

/* MODEL FAILED
 * The LLM chain's error output: Azure OpenAI timed out, refused, or returned
 * something the Structured Output Parser could not read. Answer at once with
 * {ok:false, reason} so the backend falls back to the POC rules well inside
 * N8N_TIMEOUT_SECONDS instead of waiting for the execution to die. */
const e = $input.first().json || {};
const err = e.error;
const msg = (err && (err.message || err.description)) || (typeof err === 'string' ? err : '') || e.message || 'model call failed';
return [{ json: { ok: false, reason: 'model_error: ' + String(msg).replace(/\s+/g, ' ').slice(0, 180) } }];

/* REJECT REQUEST
 * The request broke the webhook contract (docs/ARCHITECTURE.md section 6).
 * Answer {ok:false, reason}; the backend falls back to the POC rules. */
const r = $input.first().json || {};
return [{ json: { ok: false, reason: 'invalid_request: ' + String(r.reason || 'unknown').slice(0, 180) } }];
